#include <stdint.h>
#include <stdio.h>


#define IRQNO_TIMER2 28
#define IRQNO_I2C1 31

void TIM2_IRQHandler(void);
void I2C1_EV_IRQHandler(void);
void configure_priority(uint8_t irq_no, uint8_t priority_value);

//Assigning the base address to a macros, so that we can easily update the bit position of required IRQ
uint32_t *pNVIC_IPRBase  = (uint32_t*)0xE000E400;
uint32_t *pNVIC_ISERBase = (uint32_t*)0xE000E100;
uint32_t *pNVIC_ISPRBase = (uint32_t*)0xE000E200;
int main(void)
{
	//1.We are going to configure priority for the peripherals.
	configure_priority(IRQNO_TIMER2,0x80);
	configure_priority(IRQNO_I2C1,0x70);

	//2.Set the Interrupt Pending bit in NVIC Pending Register.
	*pNVIC_ISPRBase |=(1 << IRQNO_TIMER2);

	//3.Enable the IRQs in NVIC ISER
	*pNVIC_ISERBase |=(1 << IRQNO_I2C1);
	*pNVIC_ISERBase |=(1 << IRQNO_TIMER2);


    /* Loop forever */
	for(;;);
}
void configure_priority(uint8_t irq_no, uint8_t priority_value){
	/* Dividing it by 4, because in cortex Arm, the IPR are divided into 4 blocks
	Where each block is assigned for a single IRQ
	*/
	uint8_t ipr_block = irq_no / 4;
	uint32_t *pIPR_block = (pNVIC_IPRBase + ipr_block);
	/* To set the bit in that particular IRQ, we are getting modulus of
	4 and multiply it by 8(which is width of each IRQ block) */
	uint32_t ipr_start_position = ((irq_no % 4) * 8);
	*pIPR_block &= ~(0xFF << ipr_start_position);
	*pIPR_block |= (priority_value << ipr_start_position);
}

void TIM2_IRQHandler(void){
	printf("Entered into TIMER2 Handler\n");
	/*Since the Priority is same as timer, this will never execute the handler,
	it will not be preempt the previous interrupt
	To prempt previous interrupt, you increase the priority of this interrupt*/
	*pNVIC_ISPRBase |= (1 << IRQNO_I2C1);
	while(1);
}

void I2C1_EV_IRQHandler(void){
	printf("Entered in I2C1 Handler\n");
}
